(function(){
  "use strict";

  /* ---------- Item art (simple original flat SVG icons) ---------- */
  function ic(paths){
    return '<svg viewBox="0 0 48 48" width="100%" height="100%" aria-hidden="true">' + paths + '</svg>';
  }
  var ICONS = {
    report: ic('<rect x="12" y="6" width="24" height="36" rx="3" fill="#fff" stroke="#17203A" stroke-width="3"/><path d="M18 16h12M18 24h12M18 32h8" stroke="#2D9CDB" stroke-width="3" stroke-linecap="round"/>'),
    notebook: ic('<rect x="12" y="6" width="24" height="36" rx="3" fill="#FFE9A8" stroke="#17203A" stroke-width="3"/><path d="M19 6v36" stroke="#FF5252" stroke-width="3"/><circle cx="15.5" cy="13" r="1.8" fill="#17203A"/><circle cx="15.5" cy="24" r="1.8" fill="#17203A"/><circle cx="15.5" cy="35" r="1.8" fill="#17203A"/>'),
    badge: ic('<rect x="14" y="12" width="20" height="30" rx="4" fill="#fff" stroke="#17203A" stroke-width="3"/><rect x="20" y="5" width="8" height="9" rx="2" fill="#FFC800" stroke="#17203A" stroke-width="2.5"/><circle cx="24" cy="24" r="4.5" fill="#2D9CDB"/><path d="M17 36 q7 -6 14 0" stroke="#2D9CDB" stroke-width="3" fill="none" stroke-linecap="round"/>'),
    lanyard: ic('<path d="M16 5 L24 22 L32 5" fill="none" stroke="#FF5252" stroke-width="4" stroke-linecap="round"/><rect x="16" y="22" width="16" height="20" rx="3" fill="#1DB954" stroke="#17203A" stroke-width="3"/><circle cx="24" cy="30" r="3" fill="#fff"/>'),
    laptop: ic('<rect x="9" y="13" width="30" height="20" rx="3" fill="#BDEBFF" stroke="#17203A" stroke-width="3"/><rect x="5" y="33" width="38" height="6" rx="3" fill="#17203A"/>'),
    keys: ic('<circle cx="17" cy="17" r="8" fill="none" stroke="#FFC800" stroke-width="4"/><path d="M23 23 L38 38 M31 31 L37 25 M27 27 L32 22" stroke="#FFC800" stroke-width="4" stroke-linecap="round"/>'),
    mug: ic('<path d="M12 14 h22 v20 a5 5 0 0 1 -5 5 h-12 a5 5 0 0 1 -5 -5 z" fill="#FF7A59" stroke="#17203A" stroke-width="3"/><path d="M34 19 q9 3 0 12" fill="none" stroke="#17203A" stroke-width="3"/>'),
    folder: ic('<path d="M7 15 a3 3 0 0 1 3-3 h9 l4 5 h15 a3 3 0 0 1 3 3 v17 a3 3 0 0 1 -3 3 h-28 a3 3 0 0 1 -3-3 z" fill="#FFC800" stroke="#17203A" stroke-width="3" stroke-linejoin="round"/><path d="M7 22 h34" stroke="#17203A" stroke-width="3"/>'),
    calendar: ic('<rect x="10" y="10" width="28" height="30" rx="3" fill="#fff" stroke="#17203A" stroke-width="3"/><path d="M10 19 h28" stroke="#FF5252" stroke-width="4"/><path d="M17 6 v7 M31 6 v7" stroke="#17203A" stroke-width="3" stroke-linecap="round"/><circle cx="18" cy="27" r="2.4" fill="#2D9CDB"/><circle cx="26" cy="27" r="2.4" fill="#2D9CDB"/><circle cx="34" cy="27" r="2.4" fill="#2D9CDB"/><circle cx="18" cy="34" r="2.4" fill="#2D9CDB"/><circle cx="26" cy="34" r="2.4" fill="#2D9CDB"/>'),
    clock: ic('<circle cx="24" cy="24" r="16" fill="#fff" stroke="#17203A" stroke-width="3"/><path d="M24 15 v9 l7 4" stroke="#FF5252" stroke-width="3.5" fill="none" stroke-linecap="round" stroke-linejoin="round"/>'),
    pencil: ic('<path d="M11 37 L14.5 27.5 L33 9 a3.6 3.6 0 0 1 5.1 5.1 L19.5 32.5 z" fill="#FFC800" stroke="#17203A" stroke-width="3" stroke-linejoin="round"/><path d="M14.5 27.5 l5 5" stroke="#17203A" stroke-width="3"/>'),
    donut: ic('<circle cx="24" cy="24" r="15" fill="#FF9EC6" stroke="#17203A" stroke-width="3"/><circle cx="24" cy="24" r="6" fill="#fff" stroke="#17203A" stroke-width="3"/><circle cx="18" cy="17" r="1.8" fill="#1DB954"/><circle cx="30" cy="19" r="1.8" fill="#2D9CDB"/><circle cx="22" cy="31" r="1.8" fill="#FFC800"/>'),
    phone: ic('<rect x="15" y="6" width="18" height="36" rx="4" fill="#17203A"/><rect x="18" y="11" width="12" height="24" fill="#BDEBFF"/><circle cx="24" cy="39" r="1.8" fill="#fff"/>'),
    sale: ic('<path d="M10 10 h18 l10 10 -18 18 -10 -10 z" fill="#FF5252" stroke="#17203A" stroke-width="3" stroke-linejoin="round"/><circle cx="19" cy="19" r="3.5" fill="#fff" stroke="#17203A" stroke-width="2.5"/>'),
    chat: ic('<path d="M9 9 h30 a3 3 0 0 1 3 3 v16 a3 3 0 0 1 -3 3 h-16 l-8 8 v-8 h-6 a3 3 0 0 1 -3-3 v-16 a3 3 0 0 1 3-3 z" fill="#BDEBFF" stroke="#17203A" stroke-width="3" stroke-linejoin="round"/><circle cx="17" cy="20" r="2.3" fill="#17203A"/><circle cx="25" cy="20" r="2.3" fill="#17203A"/><circle cx="33" cy="20" r="2.3" fill="#17203A"/>'),
    barrier: ic('<path d="M24 5 L39 43 H32.5 L24 20 L15.5 43 H9 Z" fill="#FFC800" stroke="#17203A" stroke-width="3" stroke-linejoin="round"/><path d="M24 27 c2.8 3.8 4.4 6.2 4.4 8.8 a4.4 4.4 0 1 1 -8.8 0 c0-2.6 1.6-5 4.4-8.8z" fill="#2D9CDB" stroke="#17203A" stroke-width="2.2"/>'),
    box: ic('<rect x="9" y="15" width="30" height="24" rx="3" fill="#C98A4B" stroke="#17203A" stroke-width="3"/><path d="M9 24 h30 M24 15 v9" stroke="#17203A" stroke-width="3"/>'),
    chair: ic('<rect x="15" y="5" width="18" height="13" rx="3" fill="#2D9CDB" stroke="#17203A" stroke-width="3"/><rect x="11" y="23" width="26" height="7" rx="3" fill="#17203A"/><path d="M24 30 v5 M24 35 l-10 6 M24 35 l10 6" stroke="#17203A" stroke-width="3" stroke-linecap="round"/><circle cx="13" cy="44" r="2.6" fill="#17203A"/><circle cx="35" cy="44" r="2.6" fill="#17203A"/>')
  };
  var BG = { report:"#BDEBFF", notebook:"#FFF3D6", badge:"#FFE1E1", lanyard:"#D9F7E3", laptop:"#E4E0FF", keys:"#FFF3D6", mug:"#FFE9E0", folder:"#FFF3D6", calendar:"#FFE1E1", clock:"#E4E0FF", pencil:"#FFF6DB", donut:"#FFF", phone:"#FFF", sale:"#FFF", chat:"#E1F4FF", barrier:"#fff", box:"#fff", chair:"#fff" };

  /* Pool of 12 office items. A run deals three sets from it: 3, then 4, then 5. */
  var POOL = [
    {id:"report", name:"Report"}, {id:"badge", name:"Badge"}, {id:"lanyard", name:"Lanyard"},
    {id:"laptop", name:"Laptop"}, {id:"keys", name:"Keys"}, {id:"mug", name:"Mug"},
    {id:"notebook", name:"Notebook"}, {id:"phone", name:"Phone"}, {id:"folder", name:"Folder"},
    {id:"calendar", name:"Calendar"}, {id:"clock", name:"Clock"}, {id:"pencil", name:"Pencil"}
  ];
  var NON_TARGET = [
    {id:"donut", name:"Donut", kind:"distraction"},
    {id:"sale", name:"Sale sign", kind:"distraction"},
    {id:"chat", name:"Chat ping", kind:"distraction"},
    {id:"barrier", name:"Wet floor", kind:"barrier"},
    {id:"box", name:"Box stack", kind:"barrier"},
    {id:"chair", name:"Rolling chair", kind:"barrier"}
  ];
  var DISTRACTIONS = NON_TARGET.filter(function(d){ return d.kind === "distraction"; });
  var BARRIERS = NON_TARGET.filter(function(d){ return d.kind === "barrier"; });
  var PROPS = [
    {w:56, svg:'<svg viewBox="0 0 48 64" aria-hidden="true"><rect x="6" y="4" width="36" height="56" fill="#B07B4F" stroke="#17203A" stroke-width="3"/><rect x="12" y="10" width="24" height="20" fill="#96683F" stroke="#17203A" stroke-width="2.5"/><circle cx="36" cy="37" r="2.6" fill="#FFC800" stroke="#17203A" stroke-width="2"/></svg>'},
    {w:50, svg:'<svg viewBox="0 0 48 64" aria-hidden="true"><path d="M14 40 h20 l-3 20 h-14 z" fill="#C96F4A" stroke="#17203A" stroke-width="3" stroke-linejoin="round"/><path d="M24 41 C24 27 14 25 8 27 C10 35 16 39 24 41 C24 23 32 16 40 16 C40 29 32 39 24 41" fill="#3E9B4F" stroke="#17203A" stroke-width="2.5" stroke-linejoin="round"/></svg>'},
    {w:74, svg:'<svg viewBox="0 0 64 48" aria-hidden="true"><rect x="6" y="26" width="52" height="6" fill="#96683F" stroke="#17203A" stroke-width="3"/><rect x="10" y="32" width="5" height="12" fill="#17203A"/><rect x="49" y="32" width="5" height="12" fill="#17203A"/><rect x="22" y="6" width="20" height="15" rx="2" fill="#BDEBFF" stroke="#17203A" stroke-width="3"/><rect x="29" y="21" width="6" height="5" fill="#17203A"/></svg>'},
    {w:56, svg:'<svg viewBox="0 0 48 64" aria-hidden="true"><rect x="6" y="4" width="36" height="56" fill="rgba(189,235,255,.5)" stroke="#17203A" stroke-width="3"/><path d="M6 32 h36 M24 4 v56" stroke="#17203A" stroke-width="2"/></svg>'}
  ];

  /* ---------- Sound: tiny WebAudio blips, no audio files ---------- */
  var AC = null;
  function initAudio(){
    try{
      if (!AC) AC = new (window.AudioContext || window.webkitAudioContext)();
      if (AC.state === "suspended") AC.resume();
    }catch(e){ AC = null; }
  }
  function tone(freq, delay, dur, type, vol){
    if (!AC) return;
    try{
      var t = AC.currentTime + delay;
      var o = AC.createOscillator(), g = AC.createGain();
      o.type = type; o.frequency.value = freq;
      g.gain.setValueAtTime(vol, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + dur);
      o.connect(g); g.connect(AC.destination);
      o.start(t); o.stop(t + dur + 0.03);
    }catch(e){}
  }
  function sfx(name){
    if (!AC) return;
    if (name === "pickup"){ tone(660, 0, .09, "sine", .14); tone(990, .07, .13, "sine", .12); }
    else if (name === "wrong"){ tone(170, 0, .16, "square", .07); }
    else if (name === "miss"){ tone(300, 0, .1, "sine", .07); tone(215, .08, .15, "sine", .07); }
    else if (name === "crash"){ tone(90, 0, .35, "triangle", .22); tone(55, .02, .42, "sine", .2); }
    else if (name === "set"){ [523,659,784].forEach(function(f,i){ tone(f, i*.09, .15, "sine", .12); }); }
    else if (name === "win"){ [523,659,784,1046,1318].forEach(function(f,i){ tone(f, i*.11, .22, "sine", .12); }); }
  }
  document.addEventListener("pointerdown", initAudio, {once:false});

  /* ---------- Mascot sprites ---------- */
  var RUN_FRAMES = ["data:image/png;base64,", "data:image/png;base64,", "data:image/webp;base64,", "data:image/png;base64,"];
  var SPRITE_SRC = {
    idle: "data:image/png;base64,", jump: "data:image/png;base64,", slide: "data:image/png;base64,",
    stumble: "data:image/png;base64,", crash: "data:image/webp;base64,", celebrate: "data:image/webp;base64,"
  };
  RUN_FRAMES.concat([SPRITE_SRC.idle, SPRITE_SRC.jump, SPRITE_SRC.slide, SPRITE_SRC.stumble, SPRITE_SRC.crash, SPRITE_SRC.celebrate, "data:image/png;base64,"])
    .forEach(function(src){ var pre = new Image(); pre.src = src; });

  /* ---------- DOM ---------- */
  var corridor = document.getElementById("corridor");
  var runner = document.getElementById("runner");
  var runnerImg = document.getElementById("runner-img");
  var runnerShadow = document.getElementById("runner-shadow");
  var banner = document.getElementById("run-toast");
  var edgeToast = document.getElementById("edge-toast");
  var corridorPanel = document.getElementById("corridor-panel");
  var hintBubble = document.getElementById("hint-bubble");
  var hudSlots = document.getElementById("hud-slots");
  var hudDistance = document.getElementById("hud-distance");
  var hudScore = document.getElementById("hud-score");
  var hudMulti = document.getElementById("hud-multi");
  var hudFound = document.getElementById("hud-found");
  var strikeDots = document.querySelectorAll("#hud-strikes .strike-dot");
  var btnPeek = document.getElementById("btn-peek");
  var floorScrollEl = document.getElementById("floor-scroll");
  var laneX = ["16.6%", "50%", "83.3%"];
  var laneCenterPct = [16.6, 50, 83.3];
  var reduceMotion = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  var FRAME_MS = 1000 / 12;

  /* ---------- Session bests (real runs only, this session) ---------- */
  var bests = { distance: 0, score: 0, streak: 0 };
  var runsPlayed = 0;
  function renderBests(){
    var row = document.getElementById("best-row");
    if (!runsPlayed){
      row.innerHTML = '<div class="chip wide">No runs yet. Your bests will show here after a run.</div>';
      return;
    }
    row.innerHTML =
      '<div class="chip"><span class="chip-value">' + Math.floor(bests.distance) + ' m</span><span class="chip-label">Best distance</span></div>' +
      '<div class="chip"><span class="chip-value">' + bests.score + '</span><span class="chip-label">Best score</span></div>' +
      '<div class="chip"><span class="chip-value">' + bests.streak + (bests.streak === 1 ? ' set' : ' sets') + '</span><span class="chip-label">Best set streak</span></div>';
  }

  /* ---------- Game state ---------- */
  var game = null;
  function shuffledSets(){
    var ids = POOL.slice();
    for (var i = ids.length - 1; i > 0; i--){
      var j = Math.floor(Math.random() * (i + 1));
      var t = ids[i]; ids[i] = ids[j]; ids[j] = t;
    }
    return [ids.slice(0, 3), ids.slice(3, 7), ids.slice(7, 12)];
  }
  function resetGame(){
    game = {
      sets: shuffledSets(),
      lane: 1, distance: 0, score: 0, multi: 1, peakMulti: 1, setsDone: 0,
      setIndex: 0, collected: {}, outcomes: {}, offers: {}, inflight: {},
      strikes: 0, peekUsed: false, items: [], props: [],
      phase: "idle", phaseUntil: 0, running: false, paused: false,
      startTime: 0, spawnTimer: 0, propTimer: 0, spawnsInSet: 0, sinceTarget: 0,
      distractLeft: (typeof FR !== "undefined" && FR) ? (FR.distractQuota || 0) : 0, sinceDistract: 0,
      slowUntil: 0, scrollY: 0, spritePhase: 0, endReason: null
    };
  }
  resetGame();

  /* ---------- Extension bridge (Career Path races live in path.js) ----------
     Inert during free runs: FR knobs sit at their defaults and no end hook is
     registered, so every formula below behaves exactly as before. path.js
     drives a race by dealing custom sets, setting pace knobs, and vetoing
     the free-run summary through the end hook while a race is active. */
  var FR = { speedMul: 1, decoyBias: 0, endHook: null, flashBase: null, barrierP: 0.4, spawnMul: 1, distractQuota: 0 };
  /* Checklist flash length for a set: Path levels set FR.flashBase (the
     level's flash for a 3-item set, +250 ms per extra item). Free runs keep
     the legacy windows exactly. */
  function flashMsFirst(setLen){
    if (FR.flashBase) return Math.max(800, FR.flashBase + (setLen - 3) * 250);
    return 2100;
  }
  function flashMsNext(setLen){
    if (FR.flashBase) return Math.max(800, FR.flashBase + (setLen - 3) * 250);
    return 2000 + (setLen - 3) * 400;
  }
  function dealSets(sizes){
    var ids = POOL.slice();
    for (var i = ids.length - 1; i > 0; i--){
      var j = Math.floor(Math.random() * (i + 1));
      var t = ids[i]; ids[i] = ids[j]; ids[j] = t;
    }
    var out = [], at = 0;
    for (var s = 0; s < sizes.length; s++){ out.push(ids.slice(at, at + sizes[s])); at += sizes[s]; }
    while (out.length < 3) out.push(out[out.length - 1].slice());
    return out;
  }
  window.FocusRunAPI = {
    game: function(){ return game; },
    showScreen: showScreen,
    stopRun: stopRun,
    startRaceRun: function(sizes){
      initAudio();
      resetGame();
      game.sets = dealSets(sizes);
      playFlash(0, true);
    },
    setPace: function(mul, decoyBias){ FR.speedMul = mul || 1; FR.decoyBias = decoyBias || 0; },
    setLevel: function(opts){
      opts = opts || {};
      FR.flashBase = opts.flashMs || null;
      FR.barrierP = typeof opts.barrierP === "number" ? opts.barrierP : 0.4;
      FR.spawnMul = opts.spawnMul || 1;
      FR.distractQuota = opts.distracts || 0;
    },
    setEndHook: function(fn){ FR.endHook = fn; },
    setPaused: function(b){ if (game) game.paused = !!b; },
    sfx: sfx
  };

  /* ---------- Screen switching ---------- */
  var current = 1;
  var screens = {};
  for (var i = 1; i <= 5; i++) screens[i] = document.getElementById("screen-" + i);

  function showScreen(n){
    current = n;
    for (var k = 1; k <= 5; k++) screens[k].classList.toggle("active", k === n);
    if (n !== 3) stopRun();
    fitStage();
    window.scrollTo({top:0, behavior:"smooth"});
  }
  document.querySelectorAll("[data-go]").forEach(function(el){
    el.addEventListener("click", function(){ showScreen(Number(el.getAttribute("data-go"))); });
  });

  /* ---------- Desktop: scale the centered stage up to fit the window ---------- */
  var phoneEl = document.getElementById("phone");
  var stageScale = document.getElementById("stage-scale");
  var stageRow = stageScale.parentElement;
  function fitStage(){
    if (window.innerWidth < 1024){
      phoneEl.style.transform = "";
      stageScale.style.width = ""; stageScale.style.height = "";
      return;
    }
    var w = phoneEl.offsetWidth, h = phoneEl.offsetHeight;
    if (!w || !h) return;
    var avail = stageRow.clientWidth;
    var docTop = stageRow.getBoundingClientRect().top + window.pageYOffset;
    var availH = window.innerHeight - docTop - 14;
    var s = Math.min(1.5, availH / h, avail / w);
    if (s < 0.4) s = 0.4;
    phoneEl.style.transform = "scale(" + s + ")";
    stageScale.style.width = (w * s) + "px";
    stageScale.style.height = (h * s) + "px";
  }
  window.addEventListener("resize", fitStage);

  /* ---------- Checklist flash (screen 2, set 1 of a run) ---------- */
  var needList = document.getElementById("need-list");
  var timerFill = document.getElementById("timer-fill");
  var flashSetIndex = 0;
  var flashTimer = null;
  var flashThenRun = false;
  function renderNeedList(set){
    needList.innerHTML = "";
    set.forEach(function(item){
      var card = document.createElement("div");
      card.className = "need-card";
      card.innerHTML = '<div class="need-icon" style="background:' + BG[item.id] + '">' + ICONS[item.id] + '</div>' +
        '<div class="need-name">' + item.name + '</div>';
      needList.appendChild(card);
    });
  }
  function startFlashWindow(){
    timerFill.classList.remove("draining");
    void timerFill.offsetWidth;
    var fms = flashMsFirst(game.sets[flashSetIndex].length);
    timerFill.style.animationDuration = FR.flashBase ? (fms / 1000) + "s" : "";
    timerFill.classList.add("draining");
    if (flashTimer) clearTimeout(flashTimer);
    if (flashThenRun){
      flashTimer = setTimeout(function(){ if (current === 2) beginRun(); }, fms);
    }
  }
  function playFlash(setIndex, thenRun){
    flashSetIndex = setIndex;
    flashThenRun = thenRun;
    renderNeedList(game.sets[setIndex]);
    showScreen(2);
    startFlashWindow();
  }
  document.getElementById("btn-show-again").addEventListener("click", function(){ startFlashWindow(); });
  document.getElementById("btn-start-run").addEventListener("click", function(){
    if (flashTimer) clearTimeout(flashTimer);
    beginRun();
  });
  document.getElementById("btn-run").addEventListener("click", function(){ initAudio(); resetGame(); playFlash(0, true); });
  document.getElementById("btn-how-run").addEventListener("click", function(){ initAudio(); resetGame(); playFlash(0, true); });
  document.getElementById("btn-again").addEventListener("click", function(){ initAudio(); resetGame(); playFlash(0, true); });

  /* ---------- Sprites ---------- */
  var spriteMode = "idle";
  var spriteHoldUntil = 0;
  function setSprite(mode){
    spriteMode = mode;
    if (mode === "run"){ runnerImg.src = RUN_FRAMES[Math.floor(game.spritePhase / FRAME_MS) % 4]; }
    else runnerImg.src = SPRITE_SRC[mode];
  }
  function holdSprite(mode, ms){
    setSprite(mode);
    spriteHoldUntil = performance.now() + ms;
    setTimeout(function(){
      if (spriteMode === mode && performance.now() >= spriteHoldUntil - 40){
        if (game && game.running) setSprite("run");
        else if (mode === "jump" || mode === "slide") setSprite("idle");
      }
    }, ms + 50);
  }

  /* ---------- HUD ---------- */
  var TICK_SVG = '<svg class="tick" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 13 L10 19 L20 5" fill="none" stroke="#fff" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/></svg>';
  function renderSlots(popId){
    hudSlots.innerHTML = "";
    game.sets[game.setIndex].forEach(function(item){
      var s = document.createElement("div");
      var done = !!game.collected[item.id];
      s.className = "slot" + (done ? " done" : "") + (popId === item.id ? " pop" : "");
      s.innerHTML = '<span class="slot-q">?</span>' + TICK_SVG;
      hudSlots.appendChild(s);
    });
    updateMeta();
  }
  function updateMeta(){
    var set = game.sets[game.setIndex];
    var found = set.filter(function(it){ return game.collected[it.id]; }).length;
    hudFound.textContent = "Found " + found + " of " + set.length;
    hudMulti.textContent = "x" + game.multi;
    hudScore.textContent = game.score;
    strikeDots.forEach(function(d, i){ d.classList.toggle("used", i < game.strikes); });
    btnPeek.disabled = game.peekUsed || !game.running || game.phase !== "run";
    btnPeek.textContent = game.peekUsed ? "Peek used" : "Peek · 1";
  }
  function showBanner(text, cls){
    banner.textContent = text;
    banner.className = "run-toast " + (cls || "");
    void banner.offsetWidth;
    banner.classList.add("show");
  }
  function showEdgeToast(text, cls){
    edgeToast.textContent = text;
    edgeToast.className = "edge-toast " + (cls || "");
    void edgeToast.offsetWidth;
    edgeToast.classList.add("show");
  }
  function panelItemsHTML(set){
    return set.map(function(item){
      return '<span class="cp-item"><span class="cp-ic" style="background:' + BG[item.id] + '">' + ICONS[item.id] + '</span><span class="cp-name">' + item.name + '</span></span>';
    }).join("");
  }
  function showPanel(head, set, ms){
    corridorPanel.innerHTML = '<div class="cp-head">' + head + '</div><div class="cp-items">' + panelItemsHTML(set) + '</div>';
    corridorPanel.classList.add("show");
    if (ms) setTimeout(function(){ corridorPanel.classList.remove("show"); }, ms);
  }
  function hidePanel(){ corridorPanel.classList.remove("show"); }

  /* ---------- Juice: floaters and particles ---------- */
  function corridorPos(el, item){
    if (item && item.sprite3 && typeof T3 !== "undefined" && T3.ready){
      var p3 = T3.spriteScreenPos(item);
      if (p3) return p3;
    }
    var c = corridor.getBoundingClientRect(), r = el.getBoundingClientRect();
    var s = phoneEl.getBoundingClientRect().width / phoneEl.offsetWidth || 1;
    return { x: (r.left - c.left + r.width / 2) / s, y: (r.top - c.top + r.height / 2) / s };
  }
  function floater(x, y, text){
    var f = document.createElement("div");
    f.className = "score-floater";
    f.textContent = text;
    f.style.left = (x - 24) + "px";
    f.style.top = (y - 16) + "px";
    corridor.appendChild(f);
    var anim = f.animate([
      { transform: "translateY(0)", opacity: 1 },
      { transform: "translateY(-52px)", opacity: 0 }
    ], { duration: 820, easing: "cubic-bezier(.65,0,.35,1)" });
    anim.onfinish = function(){ f.remove(); };
  }
  function burst(x, y, n, colors, dist){
    for (var i = 0; i < n; i++){
      var p = document.createElement("span");
      p.className = "particle";
      p.style.background = colors[i % colors.length];
      p.style.left = x + "px"; p.style.top = y + "px";
      corridor.appendChild(p);
      var ang = Math.random() * Math.PI * 2;
      var d = (dist || 34) * (0.5 + Math.random() * 0.8);
      var dx = Math.cos(ang) * d, dy = Math.sin(ang) * d - 10;
      var anim = p.animate([
        { transform: "translate(0,0) rotate(0deg)", opacity: 1 },
        { transform: "translate(" + dx + "px," + dy + "px) rotate(160deg)", opacity: 0 }
      ], { duration: 460 + Math.random() * 220, easing: "cubic-bezier(.65,0,.35,1)" });
      anim.onfinish = (function(el){ return function(){ el.remove(); }; })(p);
    }
  }

  /* ---------- Movement and input ---------- */
  function moveLane(dir){
    if (!game) return;
    var before = game.lane;
    game.lane = Math.max(0, Math.min(2, game.lane + dir));
    runner.style.left = laneX[game.lane];
    runnerShadow.style.left = laneX[game.lane];
    if (game.running && game.lane !== before) holdSprite("jump", 250);
    if (game.lane !== before && typeof T3 !== "undefined" && T3.ready) T3.laneChanged();
  }
  var suppressClickUntil = 0;
  document.getElementById("tap-left").addEventListener("click", function(){ if (Date.now() > suppressClickUntil) moveLane(-1); });
  document.getElementById("tap-right").addEventListener("click", function(){ if (Date.now() > suppressClickUntil) moveLane(1); });
  var pStart = null;
  corridor.addEventListener("pointerdown", function(e){ pStart = { x: e.clientX }; });
  corridor.addEventListener("pointermove", function(e){
    if (!pStart || !game || !game.running) return;
    var dx = e.clientX - pStart.x;
    if (dx > 40){ moveLane(1); pStart = { x: e.clientX }; suppressClickUntil = Date.now() + 350; }
    else if (dx < -40){ moveLane(-1); pStart = { x: e.clientX }; suppressClickUntil = Date.now() + 350; }
  });
  corridor.addEventListener("pointerup", function(){ pStart = null; });
  corridor.addEventListener("pointercancel", function(){ pStart = null; });
  document.addEventListener("keydown", function(e){
    if (current !== 3) return;
    if (e.key === "ArrowLeft") moveLane(-1);
    if (e.key === "ArrowRight") moveLane(1);
  });
  btnPeek.addEventListener("click", function(){
    if (!game.running || game.phase !== "run" || game.peekUsed) return;
    game.peekUsed = true;
    game.multi = 1;
    showPanel("Your list", game.sets[game.setIndex], 1000);
    updateMeta();
  });
  document.getElementById("btn-end").addEventListener("click", function(){
    if (game.running) endRun("ended");
  });

  /* ---------- Spawning ---------- */
  function pickSpawnDef(){
    var set = game.sets[game.setIndex];
    var pending = set.filter(function(it){ return !game.collected[it.id] && !game.outcomes[it.id] && !game.inflight[it.id]; });
    var needOffers = pending.filter(function(it){ return (game.offers[it.id] || 0) < 2; });
    var wantTarget = needOffers.length > 0 && (Math.random() < 0.55 || game.sinceTarget >= 3);
    if (wantTarget){
      needOffers.sort(function(a, b){ return (game.offers[a.id] || 0) - (game.offers[b.id] || 0); });
      var t = needOffers[0];
      game.sinceTarget = 0;
      return { id: t.id, name: t.name, kind: "target" };
    }
    if (pending.length && Math.random() < 0.3){
      var t2 = pending[Math.floor(Math.random() * pending.length)];
      game.sinceTarget = 0;
      return { id: t2.id, name: t2.name, kind: "target" };
    }
    game.sinceTarget++;
    /* Scheduled distraction events (Path levels): if the level's quota is
       unmet and no distraction has appeared for a while, deal one now.
       Targets keep priority, so a level can never starve its own list. */
    if (game.distractLeft > 0 && game.sinceDistract >= 6){
      var dq = DISTRACTIONS[Math.floor(Math.random() * DISTRACTIONS.length)];
      return { id: dq.id, name: dq.name, kind: "distraction" };
    }
    var r = Math.random();
    if (r < 0.38 + FR.decoyBias){
      var decoys = POOL.filter(function(p){ return !set.some(function(s){ return s.id === p.id; }); });
      var d = decoys[Math.floor(Math.random() * decoys.length)];
      return { id: d.id, name: d.name, kind: "decoy" };
    }
    /* Hazard mix: barrier cadence is FR.barrierP (default 0.4, the legacy
       uniform share); the rest of the hazards are distractions. */
    if (Math.random() < FR.barrierP){
      var b = BARRIERS[Math.floor(Math.random() * BARRIERS.length)];
      return { id: b.id, name: b.name, kind: "barrier" };
    }
    var n = DISTRACTIONS[Math.floor(Math.random() * DISTRACTIONS.length)];
    return { id: n.id, name: n.name, kind: "distraction" };
  }
  function spawnItem(){
    var def = pickSpawnDef();
    if (def.kind === "distraction"){
      if (game.distractLeft > 0) game.distractLeft--;
      game.sinceDistract = 0;
    } else {
      game.sinceDistract++;
    }
    var lane = Math.floor(Math.random() * 3);
    var el = document.createElement("div");
    el.className = "lane-item kind-" + def.kind;
    el.style.left = "50%";
    el.style.top = "-110px";
    el.innerHTML = '<span class="li-ic">' + ICONS[def.id] + '</span><span class="li-name">' + def.name + '</span>';
    corridor.appendChild(el);
    if (def.kind === "target"){
      game.offers[def.id] = (game.offers[def.id] || 0) + 1;
      game.inflight[def.id] = true;
    }
    var newItem = { el: el, lane: lane, z: 0, def: def, hit: false, sprite3: null };
    if (typeof T3 !== "undefined" && T3.ready) T3.makeItemSprite(newItem);
    game.items.push(newItem);
    game.spawnsInSet++;
  }
  function spawnProp(){
    if (typeof T3 !== "undefined" && T3.ready){ T3.spawnProp3(); return; }
    var def = PROPS[Math.floor(Math.random() * PROPS.length)];
    var side = Math.random() < 0.5 ? -1 : 1;
    var near = Math.random() < 0.45;
    var el = document.createElement("div");
    el.className = "prop";
    el.style.width = def.w + "px";
    el.innerHTML = def.svg;
    corridor.appendChild(el);
    game.props.push({ el: el, side: side, near: near, z: 0 });
  }
  function removeItem(it){
    var idx = game.items.indexOf(it);
    if (idx >= 0) game.items.splice(idx, 1);
    if (it.sprite3 && typeof T3 !== "undefined") T3.removeSprite(it);
    if (it.def.kind === "target") game.inflight[it.def.id] = false;
  }
  function clearItems(){
    game.items.forEach(function(it){
      it.el.remove();
      if (it.sprite3 && typeof T3 !== "undefined") T3.removeSprite(it);
    });
    game.items = [];
    game.inflight = {};
  }

  /* ---------- Run flow ---------- */
  function beginSet(idx){
    game.setIndex = idx;
    game.collected = {};
    game.offers = {};
    game.inflight = {};
    game.spawnsInSet = 0;
    game.sinceTarget = 0;
    game.spawnTimer = 400;
    renderSlots();
  }
  function beginRun(){
    game.setIndex = 0;
    game.lane = 1;
    runner.style.left = laneX[1];
    runnerShadow.style.left = laneX[1];
    if (!game.startTime) game.startTime = Date.now();
    game.running = true;
    game.phase = "run";
    spriteHoldUntil = 0;
    setSprite("run");
    if (typeof T3 !== "undefined" && T3.ready) T3.onRunStart();
    beginSet(0);
    showScreen(3);
    if (runsPlayed === 0){
      hintBubble.classList.remove("show");
      void hintBubble.offsetWidth;
      hintBubble.classList.add("show");
    }
  }
  function setResolved(){
    return game.sets[game.setIndex].every(function(it){ return game.collected[it.id] || game.outcomes[it.id]; });
  }
  function setComplete(){
    game.setsDone += 1;
    game.multi += 1;
    if (game.multi > game.peakMulti) game.peakMulti = game.multi;
    clearItems();
    holdSprite("celebrate", 1000);
    sfx("set");
    game.phase = "celebrate";
    if (game.setIndex === 2){
      showBanner("Set complete", "good");
      game.phaseUntil = performance.now() + 1300;
    } else {
      showBanner("Set complete", "good");
      game.phaseUntil = performance.now() + 2000;
    }
    updateMeta();
  }
  function startWin(){
    game.phase = "winshow";
    game.phaseUntil = performance.now() + 1800;
    setSprite("celebrate");
    spriteHoldUntil = performance.now() + 1750;
    showBanner("You win", "good");
    sfx("win");
    var c = corridor.getBoundingClientRect();
    var s = phoneEl.getBoundingClientRect().width / phoneEl.offsetWidth || 1;
    burst(c.width / s / 2, c.height / s * 0.4, 26, ["#FFC800", "#0D8039", "#2D9CDB", "#D92B2B", "#FF7A59"], 90);
  }
  function crash(){
    game.running = false;
    game.phase = "over";
    spriteHoldUntil = 0;
    runner.style.transform = "";
    setSprite("stumble");
    setTimeout(function(){ setSprite("crash"); }, 450);
    runner.classList.remove("shake");
    void runner.offsetWidth;
    runner.classList.add("shake");
    setTimeout(function(){ runner.classList.remove("shake"); }, 560);
    showBanner("Crash", "bad");
    sfx("crash");
    if (typeof T3 !== "undefined" && T3.ready) T3.onCrash();
    setTimeout(function(){ endRun("crash"); }, 1050);
  }
  function finalizeOutcomes(){
    game.sets[game.setIndex].forEach(function(it){
      if (!game.collected[it.id] && !game.outcomes[it.id] && (game.offers[it.id] || 0) >= 1){
        game.outcomes[it.id] = "missed";
      }
    });
  }
  function endRun(reason){
    if (FR.endHook && FR.endHook(reason)) return;
    if (game.endReason) return;
    game.endReason = reason;
    game.running = false;
    game.phase = "over";
    finalizeOutcomes();
    runsPlayed += 1;
    if (game.distance > bests.distance) bests.distance = game.distance;
    if (game.score > bests.score) bests.score = game.score;
    if (game.setsDone > bests.streak) bests.streak = game.setsDone;
    renderBests();
    var secs = Math.max(1, Math.round((Date.now() - (game.startTime || Date.now())) / 1000));
    fillSummary(reason, secs);
    showScreen(4);
  }
  function stopRun(){
    if (game){ game.running = false; if (game.phase !== "over") game.phase = "idle"; clearItems(); }
    corridorPanel.classList.remove("show");
    runner.style.transform = "";
    if (spriteMode !== "crash") setSprite("idle");
  }

  /* ---------- Hits ---------- */
  function onHit(it){
    var def = it.def;
    if (def.kind === "target" && !game.collected[def.id]){
      game.collected[def.id] = true;
      game.outcomes[def.id] = "got";
      var gained = 100 * game.multi;
      game.score += gained;
      if (typeof T3 !== "undefined" && T3.ready) T3.onPickup();
      var pos = corridorPos(it.el, it);
      floater(pos.x, pos.y, "+" + gained);
      burst(pos.x, pos.y, 7, ["#FFC800", "#0D8039", "#2D9CDB"], 36);
      sfx("pickup");
      it.el.classList.add("collected");
      var el = it.el;
      setTimeout(function(){ el.remove(); }, 300);
      removeItem(it);
      renderSlots(def.id);
      showEdgeToast(def.name + " ticked off", "good");
      if (setResolved()) setComplete();
    } else if (def.kind === "barrier"){
      it.el.remove(); removeItem(it);
      crash();
    } else if (def.kind === "decoy"){
      it.el.remove(); removeItem(it);
      if (typeof T3 !== "undefined" && T3.ready) T3.onHitReact();
      game.multi = 1;
      game.slowUntil = performance.now() + 750;
      runner.classList.remove("wobble");
      void runner.offsetWidth;
      runner.classList.add("wobble");
      showEdgeToast("Not on your list. Multiplier reset", "bad");
      sfx("wrong");
      updateMeta();
    } else {
      it.el.remove(); removeItem(it);
      if (typeof T3 !== "undefined" && T3.ready) T3.onDistract();
      corridor.classList.remove("pull");
      void corridor.offsetWidth;
      corridor.classList.add("pull");
      holdSprite("slide", 380);
      showEdgeToast("Distraction. Keep going");
    }
  }
  function onTargetPass(it){
    var def = it.def;
    delete game.inflight[def.id];
    if ((game.offers[def.id] || 0) >= 2 && !game.collected[def.id] && !game.outcomes[def.id]){
      game.outcomes[def.id] = "missed";
    }
    game.strikes += 1;
    sfx("miss");
    showEdgeToast("One slipped past. Strike " + game.strikes + " of 3", "bad");
    updateMeta();
    if (game.strikes >= 3){
      game.running = false;
      game.phase = "over";
      showBanner("Three strikes", "bad");
      setTimeout(function(){ endRun("strikes"); }, 950);
      return;
    }
    if (setResolved()) setComplete();
  }

  /* ---------- 3D stage: Three.js corridor and skeletal runner ----------
     The runner model is the Quaternius suit character from the local asset
     library (https://cdn.jsdelivr.net/gh/umairismail233/3d-asset-library@main/01-characters/quaternius-ultimate-animated-character-suit-male.glb). Its Run, Walk, Idle, PickUp, RecieveHit,
     Death and Victory clips ship inside the same GLB on the same rig, so no
     cross rig graft is needed and the stride is true skeletal motion.
     Loading runs through one THREE.LoadingManager. Any failure (no WebGL,
     no THREE, load error, timeout) leaves T3.ready false and the existing
     2D sprite runner keeps the game exactly as it was. */
  var T3 = {
    ready: false, failed: false, current: null, onceUntil: 0,
    crashActive: false, tip: 0, dipT: -1, tiltT: -1,
    x: 0, fromX: 0, toX: 0, glideStart: 0, bank: 0,
    scroll: 0, props: [], w: 0, h: 0, clock: 0
  };
  (function initThree(){
    var wrap = document.getElementById("gl-wrap");
    var loadPill = document.getElementById("gl-loading");
    if (!window.THREE || !THREE.GLTFLoader){ T3.failed = true; return; }
    var renderer;
    try{
      renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: "high-performance" });
    }catch(e){ T3.failed = true; return; }
    if (!renderer){ T3.failed = true; return; }
    loadPill.classList.add("show");
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    wrap.appendChild(renderer.domElement);
    T3.renderer = renderer;

    function cssVar(name, fallback){
      try{
        var v = getComputedStyle(document.documentElement).getPropertyValue(name).trim();
        return v || fallback;
      }catch(e){ return fallback; }
    }
    var wallCol = cssVar("--wall", "#F6E7C1");
    var floorCol = cssVar("--floor1", "#EFC979");
    var inkCol = cssVar("--line", "#17203A");

    var scene = new THREE.Scene();
    scene.background = new THREE.Color(wallCol);
    scene.fog = new THREE.Fog(new THREE.Color(wallCol).getHex(), 24, 60);
    T3.scene = scene;
    var camera = new THREE.PerspectiveCamera(55, 1, 0.1, 120);
    camera.position.set(0, 2.8, 7.6);
    camera.lookAt(0, 1.02, -6);
    T3.camera = camera;
    scene.add(new THREE.HemisphereLight(0xffffff, 0x66707F, 1.0));
    var dl = new THREE.DirectionalLight(0xffffff, 0.75);
    dl.position.set(3, 7, 5);
    scene.add(dl);

    /* Floor: office carpet tiles with a deep ink runner down the middle.
       The runner band carries the three lanes; its sky edges and the soft
       lane dashes keep the track readable without shouting over the cards.
       The plane is 9.4 wide, so u = (x + 4.7) / 9.4: the runner spans
       x -2.55..2.55 (u .229.. .771), lane guides sit at x -0.85 and +0.85. */
    function makeFloorTexture(){
      var c = document.createElement("canvas"); c.width = 512; c.height = 512;
      var g = c.getContext("2d");
      g.fillStyle = floorCol; g.fillRect(0, 0, 512, 512);
      var i, j;
      for (i = 0; i < 2400; i++){
        g.fillStyle = Math.random() < 0.5 ? "rgba(255,255,255,.05)" : "rgba(10,16,34,.06)";
        g.fillRect(Math.random() * 512, Math.random() * 512, 2, 2);
      }
      g.strokeStyle = "rgba(16,24,40,.32)"; g.lineWidth = 3;
      for (i = 0; i <= 512; i += 128){
        g.beginPath(); g.moveTo(0, i); g.lineTo(512, i); g.stroke();
        g.beginPath(); g.moveTo(i, 0); g.lineTo(i, 512); g.stroke();
      }
      g.fillStyle = "#2B3350"; g.fillRect(117, 0, 278, 512);
      for (j = 0; j < 500; j++){
        g.fillStyle = "rgba(255,255,255,.05)";
        g.fillRect(117 + Math.random() * 278, Math.random() * 512, 2, 2);
      }
      g.fillStyle = "#7FB6D9"; g.fillRect(117, 0, 6, 512); g.fillRect(389, 0, 6, 512);
      g.fillStyle = "rgba(230,238,248,.45)";
      for (i = 0; i < 512; i += 64){ g.fillRect(207, i, 5, 34); g.fillRect(300, i, 5, 34); }
      var t = new THREE.CanvasTexture(c);
      t.wrapS = t.wrapT = THREE.RepeatWrapping;
      t.repeat.set(1, 10);
      return t;
    }
    /* Wall: pale office panels with a glass partition band and a framed
       notice board per tile. The texture itself stays static; doors and
       glass stream past as 3D props so both walls always move in the
       correct direction. */
    function makeWallTexture(){
      var c = document.createElement("canvas"); c.width = 512; c.height = 256;
      var g = c.getContext("2d");
      g.fillStyle = wallCol; g.fillRect(0, 0, 512, 256);
      g.fillStyle = "rgba(23,32,58,.16)"; g.fillRect(0, 168, 512, 6);
      var grad = g.createLinearGradient(0, 24, 0, 168);
      grad.addColorStop(0, "rgba(189,235,255,.95)");
      grad.addColorStop(1, "rgba(140,190,225,.85)");
      g.fillStyle = grad; g.fillRect(28, 24, 200, 144);
      g.strokeStyle = "rgba(23,32,58,.55)"; g.lineWidth = 6;
      g.strokeRect(28, 24, 200, 144);
      g.beginPath(); g.moveTo(128, 24); g.lineTo(128, 168); g.stroke();
      g.fillStyle = "rgba(255,255,255,.35)"; g.fillRect(40, 34, 60, 124);
      g.fillStyle = "#FFFFFF"; g.fillRect(284, 40, 176, 112);
      g.strokeStyle = "rgba(23,32,58,.55)"; g.strokeRect(284, 40, 176, 112);
      g.fillStyle = "rgba(217,43,43,.5)"; g.fillRect(300, 58, 66, 12);
      g.fillStyle = "rgba(23,32,58,.35)";
      g.fillRect(300, 84, 144, 9); g.fillRect(300, 104, 120, 9); g.fillRect(300, 124, 136, 9);
      g.fillStyle = "rgba(23,32,58,.12)"; g.fillRect(0, 0, 5, 256);
      var t = new THREE.CanvasTexture(c);
      t.wrapS = t.wrapT = THREE.RepeatWrapping;
      t.repeat.set(12, 1);
      return t;
    }
    /* Ceiling: pale tiles with a glowing light panel per tile (unlit
       material, so the panels always read as lit). */
    function makeCeilingTexture(){
      var c = document.createElement("canvas"); c.width = 256; c.height = 256;
      var g = c.getContext("2d");
      g.fillStyle = "#E9EDF4"; g.fillRect(0, 0, 256, 256);
      g.strokeStyle = "rgba(23,32,58,.18)"; g.lineWidth = 3;
      g.strokeRect(6, 6, 244, 244);
      g.fillStyle = "#FFFFFF"; g.fillRect(48, 88, 160, 80);
      g.strokeStyle = "rgba(23,32,58,.28)"; g.lineWidth = 4;
      g.strokeRect(48, 88, 160, 80);
      g.fillStyle = "rgba(189,235,255,.5)"; g.fillRect(56, 96, 144, 64);
      var t = new THREE.CanvasTexture(c);
      t.wrapS = t.wrapT = THREE.RepeatWrapping;
      t.repeat.set(1, 12);
      return t;
    }
    var floorTex = makeFloorTexture();
    var wallTex = makeWallTexture();
    T3.floorTex = floorTex;
    var floor = new THREE.Mesh(
      new THREE.PlaneGeometry(9.4, 62),
      new THREE.MeshLambertMaterial({ map: floorTex })
    );
    floor.rotation.x = -Math.PI / 2;
    floor.position.set(0, 0, -24);
    scene.add(floor);
    [-4.7, 4.7].forEach(function(wx){
      var wall = new THREE.Mesh(
        new THREE.PlaneGeometry(62, 3.4),
        new THREE.MeshLambertMaterial({ map: wallTex })
      );
      wall.rotation.y = wx < 0 ? Math.PI / 2 : -Math.PI / 2;
      wall.position.set(wx, 1.7, -24);
      scene.add(wall);
      var skirt = new THREE.Mesh(
        new THREE.BoxGeometry(0.18, 0.22, 62),
        new THREE.MeshLambertMaterial({ color: 0x46536B })
      );
      skirt.position.set(wx < 0 ? -4.55 : 4.55, 0.11, -24);
      scene.add(skirt);
    });
    var ceil = new THREE.Mesh(
      new THREE.PlaneGeometry(9.4, 62),
      new THREE.MeshBasicMaterial({ map: makeCeilingTexture() })
    );
    ceil.rotation.x = Math.PI / 2;
    ceil.position.set(0, 3.38, -24);
    scene.add(ceil);

    /* Reception at the far end of the hall: the counter he runs toward,
       with the sign and a wall clock on the back panel. Static dressing;
       the streaming props pass beside it. Fog softens it into depth. */
    (function reception(){
      var grp = new THREE.Group();
      var counter = new THREE.Mesh(new THREE.BoxGeometry(4.6, 1.12, 0.85), new THREE.MeshLambertMaterial({ color: 0xF4F6FA }));
      counter.position.set(0, 0.56, 0); grp.add(counter);
      var top = new THREE.Mesh(new THREE.BoxGeometry(4.85, 0.09, 1.0), new THREE.MeshLambertMaterial({ color: 0x96683F }));
      top.position.set(0, 1.16, 0); grp.add(top);
      var kick = new THREE.Mesh(new THREE.BoxGeometry(4.6, 0.16, 0.9), new THREE.MeshLambertMaterial({ color: 0x17203A }));
      kick.position.set(0, 0.08, 0); grp.add(kick);
      var c = document.createElement("canvas"); c.width = 512; c.height = 160;
      var g = c.getContext("2d");
      g.fillStyle = "#2B3350"; g.fillRect(0, 0, 512, 160);
      g.fillStyle = "#FFFFFF";
      g.font = "900 52px Nunito, sans-serif"; g.textAlign = "center";
      g.fillText("RECEPTION", 256, 72);
      g.beginPath(); g.arc(256, 118, 23, 0, Math.PI * 2); g.fill();
      g.strokeStyle = "#17203A"; g.lineWidth = 4; g.lineCap = "round";
      g.beginPath(); g.moveTo(256, 118); g.lineTo(256, 103); g.stroke();
      g.beginPath(); g.moveTo(256, 118); g.lineTo(267, 123); g.stroke();
      var tex = new THREE.CanvasTexture(c);
      var panel = new THREE.Mesh(new THREE.PlaneGeometry(6.4, 2.0), new THREE.MeshLambertMaterial({ map: tex }));
      panel.position.set(0, 2.05, -1.35);
      grp.add(panel);
      grp.position.set(0, 0, -33);
      scene.add(grp);
    })();

    /* Runner group: procedural layers (glide, bank, bob, dip, tip) ride on
       the group while the mixer drives the skeleton inside it. */
    var runnerGroup = new THREE.Group();
    scene.add(runnerGroup);
    T3.runnerGroup = runnerGroup;
    var shadow = new THREE.Mesh(
      new THREE.CircleGeometry(0.32, 24),
      new THREE.MeshBasicMaterial({ color: 0x17203A, transparent: true, opacity: 0.30, depthWrite: false })
    );
    shadow.rotation.x = -Math.PI / 2;
    shadow.position.y = 0.02;
    runnerGroup.add(shadow);
    T3.shadow = shadow;
    var modelHolder = new THREE.Group();
    runnerGroup.add(modelHolder);
    T3.modelHolder = modelHolder;

    /* Item card textures: same card art as the 2D items, drawn to canvas */
    var itemTextures = {};
    function itemTexture(def){
      var key = def.id + ":" + def.kind;
      if (itemTextures[key]) return itemTextures[key];
      var c = document.createElement("canvas"); c.width = 220; c.height = 248;
      var g = c.getContext("2d");
      var barrier = def.kind === "barrier";
      g.fillStyle = barrier ? "#D92B2B" : "#FFFFFF";
      g.strokeStyle = inkCol; g.lineWidth = 10;
      var r = 26;
      g.beginPath();
      g.moveTo(r, 5); g.lineTo(220 - r, 5); g.quadraticCurveTo(215, 5, 215, r);
      g.lineTo(215, 248 - r); g.quadraticCurveTo(215, 243, 220 - r, 243);
      g.lineTo(r, 243); g.quadraticCurveTo(5, 243, 5, 248 - r);
      g.lineTo(5, r); g.quadraticCurveTo(5, 5, r, 5); g.closePath();
      g.fill(); g.stroke();
      g.fillStyle = barrier ? "#FFFFFF" : inkCol;
      g.font = "900 30px Nunito, sans-serif";
      g.textAlign = "center";
      g.fillText(def.name, 110, 224, 190);
      var tex = new THREE.CanvasTexture(c);
      itemTextures[key] = tex;
      var img = new Image();
      img.onload = function(){
        var tmp = document.createElement("canvas"); tmp.width = 120; tmp.height = 120;
        var tg = tmp.getContext("2d");
        if (barrier){ tg.filter = "brightness(0) invert(1)"; }
        tg.drawImage(img, 0, 0, 120, 120);
        g.drawImage(tmp, 50, 34, 120, 120);
        tex.needsUpdate = true;
      };
      img.src = "data:image/svg+xml;charset=utf-8," + encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 48 48">' + ICONS[def.id].replace(/^<svg[^>]*>/, "").replace(/<\/svg>$/, "") + "</svg>");
      return tex;
    }
    T3.makeItemSprite = function(it){
      var mat = new THREE.SpriteMaterial({ map: itemTexture(it.def), transparent: true, opacity: 0, fog: false });
      var sp = new THREE.Sprite(mat);
      sp.center.set(0.5, 0);
      sp.scale.set(1.85, 2.08, 1);
      sp.position.set(0, 0.02, -24);
      scene.add(sp);
      it.sprite3 = sp;
    };
    T3.removeSprite = function(it){
      if (it.sprite3){ scene.remove(it.sprite3); it.sprite3.material.dispose(); it.sprite3 = null; }
    };
    var LANE_X3 = [-1.7, 0, 1.7];
    T3.placeItem = function(it, rawZ){
      if (!it.sprite3) return;
      /* 3D-only depth easing (raw z^1.55 instead of the shared z^2.1) plus a
         far boost, so cards read as objects early in the approach instead of
         popping in at the end. Raw z (timing, hits) is untouched. */
      var ez = Math.pow(rawZ, 1.55);
      it.sprite3.position.set(LANE_X3[it.lane], 0.02, -24 + ez * 28.4);
      var boost = 1 + 0.30 * (1 - ez);
      it.sprite3.scale.set(1.85 * boost, 2.08 * boost, 1);
      it.sprite3.material.opacity = it.z < 0.08 ? it.z / 0.08 : 1;
    };
    var projV = new THREE.Vector3();
    T3.spriteScreenPos = function(it){
      if (!it.sprite3 || !T3.camera) return null;
      projV.copy(it.sprite3.position); projV.y += 0.7;
      projV.project(T3.camera);
      return {
        x: (projV.x * 0.5 + 0.5) * corridor.clientWidth,
        y: (-projV.y * 0.5 + 0.5) * corridor.clientHeight
      };
    };

    /* Streaming office props: desks, plants and cabinets on both walls */
    var propMakers = [
      function(){
        var grp = new THREE.Group();
        var top = new THREE.Mesh(new THREE.BoxGeometry(1.7, 0.09, 0.85), new THREE.MeshLambertMaterial({ color: 0x96683F }));
        top.position.y = 0.78; grp.add(top);
        var leg = new THREE.Mesh(new THREE.BoxGeometry(1.5, 0.74, 0.7), new THREE.MeshLambertMaterial({ color: 0xB07B4F }));
        leg.position.y = 0.38; grp.add(leg);
        var mon = new THREE.Mesh(new THREE.BoxGeometry(0.55, 0.38, 0.05), new THREE.MeshLambertMaterial({ color: 0xBDEBFF }));
        mon.position.set(0.2, 1.05, 0); grp.add(mon);
        return grp;
      },
      function(){
        var grp = new THREE.Group();
        var pot = new THREE.Mesh(new THREE.CylinderGeometry(0.24, 0.19, 0.42, 10), new THREE.MeshLambertMaterial({ color: 0xC96F4A }));
        pot.position.y = 0.21; grp.add(pot);
        var fol = new THREE.Mesh(new THREE.IcosahedronGeometry(0.44, 0), new THREE.MeshLambertMaterial({ color: 0x3E9B4F }));
        fol.position.y = 0.82; grp.add(fol);
        return grp;
      },
      function(){
        var grp = new THREE.Group();
        var cab = new THREE.Mesh(new THREE.BoxGeometry(0.95, 1.7, 0.55), new THREE.MeshLambertMaterial({ color: 0x7A8BA8 }));
        cab.position.y = 0.85; grp.add(cab);
        var dr = new THREE.Mesh(new THREE.BoxGeometry(0.75, 0.5, 0.04), new THREE.MeshLambertMaterial({ color: 0x5D6E8C }));
        dr.position.set(0, 1.15, 0.29); grp.add(dr);
        return grp;
      },
      function(){
        var grp = new THREE.Group();
        grp.userData.wall = true;
        var slab = new THREE.Mesh(new THREE.BoxGeometry(0.1, 2.3, 1.15), new THREE.MeshLambertMaterial({ color: 0xB07B4F }));
        slab.position.y = 1.15; grp.add(slab);
        var knob = new THREE.Mesh(new THREE.SphereGeometry(0.055, 10, 8), new THREE.MeshLambertMaterial({ color: 0xFFC800 }));
        knob.position.set(0.09, 1.1, 0.38); grp.add(knob);
        return grp;
      },
      function(){ /* lobby sofa, back to the wall */
        var grp = new THREE.Group();
        var base = new THREE.Mesh(new THREE.BoxGeometry(0.82, 0.42, 1.9), new THREE.MeshLambertMaterial({ color: 0x3E7C74 }));
        base.position.y = 0.32; grp.add(base);
        var back = new THREE.Mesh(new THREE.BoxGeometry(0.24, 0.62, 1.9), new THREE.MeshLambertMaterial({ color: 0x35685F }));
        back.position.set(-0.30, 0.72, 0); grp.add(back);
        [-0.82, 0.82].forEach(function(z){
          var arm = new THREE.Mesh(new THREE.BoxGeometry(0.8, 0.3, 0.2), new THREE.MeshLambertMaterial({ color: 0x35685F }));
          arm.position.set(0, 0.62, z); grp.add(arm);
        });
        return grp;
      },
      function(){ /* office chair, back to the wall */
        var grp = new THREE.Group();
        var seat = new THREE.Mesh(new THREE.BoxGeometry(0.56, 0.08, 0.54), new THREE.MeshLambertMaterial({ color: 0x2B3350 }));
        seat.position.y = 0.52; grp.add(seat);
        var back = new THREE.Mesh(new THREE.BoxGeometry(0.08, 0.62, 0.54), new THREE.MeshLambertMaterial({ color: 0x2B3350 }));
        back.position.set(-0.26, 0.92, 0); grp.add(back);
        var stem = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.05, 0.46, 8), new THREE.MeshLambertMaterial({ color: 0x8A93A6 }));
        stem.position.y = 0.27; grp.add(stem);
        var foot = new THREE.Mesh(new THREE.CylinderGeometry(0.3, 0.32, 0.05, 12), new THREE.MeshLambertMaterial({ color: 0x8A93A6 }));
        foot.position.y = 0.03; grp.add(foot);
        return grp;
      },
      function(){ /* pillar, close to the wall */
        var grp = new THREE.Group();
        grp.userData.x = 4.28;
        var col = new THREE.Mesh(new THREE.BoxGeometry(0.55, 3.38, 0.55), new THREE.MeshLambertMaterial({ color: 0xDFE5EE }));
        col.position.y = 1.69; grp.add(col);
        var base = new THREE.Mesh(new THREE.BoxGeometry(0.66, 0.5, 0.66), new THREE.MeshLambertMaterial({ color: 0x3A4358 }));
        base.position.y = 0.25; grp.add(base);
        return grp;
      },
      function(){ /* frosted glass partition on the wall line */
        var grp = new THREE.Group();
        grp.userData.wall = true;
        var frame = new THREE.Mesh(new THREE.BoxGeometry(0.09, 2.6, 1.56), new THREE.MeshLambertMaterial({ color: 0x46536B }));
        frame.position.y = 1.3; grp.add(frame);
        var pane = new THREE.Mesh(new THREE.BoxGeometry(0.12, 2.34, 1.34), new THREE.MeshLambertMaterial({ color: 0xBDEBFF, transparent: true, opacity: 0.55 }));
        pane.position.y = 1.3; grp.add(pane);
        return grp;
      }
    ];
    T3.spawnProp3 = function(){
      if (T3.props.length >= 10) return;
      var grp = propMakers[Math.floor(Math.random() * propMakers.length)]();
      var side = Math.random() < 0.5 ? -1 : 1;
      grp.position.set(side * (grp.userData.wall ? 4.58 : (grp.userData.x || 3.55)), 0, -36 - Math.random() * 4);
      if (side > 0 && !grp.userData.wall) grp.rotation.y = Math.PI;
      scene.add(grp);
      T3.props.push(grp);
    };

    /* Animation state machine: actions joined by short crossfades only */
    function fadeTo(action, dur){
      if (!action || T3.current === action) return;
      var prev = T3.current;
      action.reset();
      action.enabled = true;
      action.setEffectiveWeight(1);
      action.fadeIn(dur);
      action.play();
      if (prev) prev.fadeOut(dur);
      T3.current = action;
    }
    T3.fadeTo = fadeTo;
    T3.laneChanged = function(){
      T3.fromX = T3.x;
      T3.toX = LANE_X3[game.lane];
      T3.glideStart = performance.now();
    };
    T3.onRunStart = function(){
      T3.crashActive = false; T3.tip = 0; T3.dipT = -1; T3.tiltT = -1; T3.onceUntil = 0;
      T3.x = LANE_X3[game.lane]; T3.fromX = T3.x; T3.toX = T3.x;
      if (T3.acts) fadeTo(T3.acts.run, 0.15);
    };
    T3.onPickup = function(){
      if (!T3.acts || T3.crashActive) return;
      T3.acts.pickup.timeScale = 1.7;
      fadeTo(T3.acts.pickup, 0.12);
      T3.onceUntil = performance.now() + 430;
    };
    T3.onHitReact = function(){
      if (!T3.acts || T3.crashActive) return;
      fadeTo(T3.acts.hit, 0.12);
      T3.onceUntil = performance.now() + 520;
      T3.tiltT = 0;
    };
    T3.onDistract = function(){ T3.dipT = 0; };
    T3.onCrash = function(){
      if (!T3.acts) return;
      T3.crashActive = true;
      T3.acts.death.timeScale = 0.95;
      fadeTo(T3.acts.death, 0.16);
    };

    T3.update = function(dtMs, st){
      if (!T3.ready) return;
      var dt = Math.min(0.05, dtMs / 1000);
      var now = performance.now();
      var w = corridor.clientWidth, h = corridor.clientHeight;
      if (w && h && (w !== T3.w || h !== T3.h)){
        T3.w = w; T3.h = h;
        renderer.setSize(w, h, false);
        camera.aspect = w / h;
        camera.updateProjectionMatrix();
      }
      /* Phase to action sync, never overriding a one shot or the crash */
      if (!T3.crashActive && now >= T3.onceUntil){
        var want = null;
        if (st.phase === "run") want = T3.acts.run;
        else if (st.phase === "flash") want = T3.acts.walk;
        else if (st.phase === "celebrate" || st.phase === "winshow") want = T3.acts.victory;
        else want = T3.acts.idle;
        if (want && want !== T3.current) fadeTo(want, 0.2);
      }
      if (T3.current === T3.acts.run){
        var ts = 1.02 * st.worldSpeed * st.fallMul + 0.18;
        T3.acts.run.timeScale = Math.max(0.5, Math.min(1.9, ts));
      }
      if (T3.mixer) T3.mixer.update(dt);

      /* Lane glide: 180 ms easeOutCubic plus a banking layer */
      var p = Math.min(1, (now - T3.glideStart) / 180);
      var e = 1 - Math.pow(1 - p, 3);
      T3.x = T3.fromX + (T3.toX - T3.fromX) * e;
      var bankTarget = p < 1 ? -Math.sign(T3.toX - T3.fromX) * 0.17 : 0;
      T3.bank += (bankTarget - T3.bank) * Math.min(1, dt * 14);
      runnerGroup.position.x = T3.x;
      runnerGroup.rotation.z = T3.bank;
      runnerGroup.rotation.y = T3.bank * 0.85;

      /* Running bob as a light procedural layer over the clip */
      var bobY = 0;
      if (!reduceMotion && T3.current === T3.acts.run && T3.mixer){
        bobY = Math.abs(Math.sin(T3.acts.run.time * Math.PI / 0.88)) * 0.045;
      }
      /* Distraction dip and decoy tilt, both brief procedural layers */
      var dipY = 0, tiltX = 0;
      if (T3.dipT >= 0){
        T3.dipT += dt / 0.38;
        if (T3.dipT >= 1) T3.dipT = -1;
        else { var ds = Math.sin(T3.dipT * Math.PI); dipY = -0.13 * ds; tiltX += 0.16 * ds; }
      }
      if (T3.tiltT >= 0){
        T3.tiltT += dt / 0.5;
        if (T3.tiltT >= 1) T3.tiltT = -1;
        else tiltX += Math.sin(T3.tiltT * Math.PI) * 0.13;
      }
      /* Crash tip: he pitches forward over his feet, then holds */
      if (T3.crashActive && T3.tip < 1){
        T3.tip = Math.min(1, T3.tip + dt / 0.7);
      }
      var tipE = 1 - Math.pow(1 - T3.tip, 2);
      runnerGroup.rotation.x = tiltX + tipE * 0.38;
      runnerGroup.position.y = bobY + dipY;
      shadow.scale.setScalar(1 - bobY * 1.4);
      shadow.material.opacity = 0.30 - bobY * 1.6;

      /* World streaming: floor and walls scroll, props approach and recycle */
      var spd = st.worldSpeed * st.fallMul;
      T3.scroll += dt * 3.6 * spd;
      floorTex.offset.y = (T3.scroll / 6.2) % 1;
      for (var i = T3.props.length - 1; i >= 0; i--){
        var pr = T3.props[i];
        pr.position.z += dt * 8.6 * spd;
        if (pr.position.z > 8.5){ scene.remove(pr); T3.props.splice(i, 1); }
      }
      renderer.render(scene, camera);
    };

    /* Model loading, two steps. Primary: https://cdn.jsdelivr.net/gh/umairismail233/3d-asset-library@main/01-characters/quaternius-ultimate-animated-character-suit-male.glb, the same
       character and clips with geometry stored uncompressed, so it needs
       no decoder at all. The compressed original depended on the meshopt
       decoder's WebAssembly, which some app shells block; there the load
       died silently and the game quietly stayed on the 2D sprite, which
       read as "the 3D model never loaded". If the plain file ever fails,
       step two retries with the compressed original plus the decoder.
       Only when both fail does the sprite runner stay, and the pill then
       says so instead of failing in silence. */
    var loadDone = false;
    var loadAttempt = -1;
    var failTimer = null;
    function fail3D(){
      if (loadDone) return;
      loadDone = true;
      T3.failed = true;
      clearTimeout(failTimer);
      loadPill.textContent = "3D unavailable · 2D runner on";
      loadPill.classList.add("show");
      setTimeout(function(){ loadPill.classList.remove("show"); }, 2600);
    }
    function armFailTimer(){
      clearTimeout(failTimer);
      failTimer = setTimeout(function(){
        if (loadAttempt === 0) tryLoad(1); else fail3D();
      }, 20000);
    }
    function tryLoad(attempt){
      if (loadDone || attempt <= loadAttempt) return;
      loadAttempt = attempt;
      armFailTimer();
      var manager = new THREE.LoadingManager();
      manager.onError = function(){ if (attempt === 0) tryLoad(1); else fail3D(); };
      var loader = new THREE.GLTFLoader(manager);
      if (attempt === 1){
        try{ loader.setMeshoptDecoder(window.MeshoptDecoder); }catch(e){}
      }
      loader.load(attempt === 0 ? "https://cdn.jsdelivr.net/gh/umairismail233/3d-asset-library@main/01-characters/quaternius-ultimate-animated-character-suit-male.glb" : "https://cdn.jsdelivr.net/gh/umairismail233/3d-asset-library@main/01-characters/quaternius-ultimate-animated-character-suit-male.glb", onModel, undefined, function(){
        if (attempt === 0) tryLoad(1); else fail3D();
      });
    }
    /* Dress shoes for the runner. The GLB's own feet are a 45-vertex
       near-black stub coloured by the SAME palette cell as the suit, so
       no material edit can separate shoe from trouser. Real shoe shells
       are parented to the foot bones instead: dark brown uppers and toe
       boxes over a light sole, built inside a group counter-rotated by
       the bone's bind world quaternion, so the parts sit in model axes
       (x width, y up, z toe-forward) and follow every clip. The fit
       boxes were measured off this exact GLB's posed bind geometry. */
    var SHOE_FIT = {
      FootL: { min: [-0.0477, -0.0604, -0.0532], max: [0.0536, 0.0316, 0.0451] },
      FootR: { min: [-0.0536, -0.0500, -0.0423], max: [0.0478, 0.0311, 0.0684] }
    };
    function addShoes(root){
      ["FootL", "FootR"].forEach(function(name){
        var bone = root.getObjectByName(name);
        var fit = SHOE_FIT[name];
        if (!bone || !fit) return;
        var bq = new THREE.Quaternion();
        bone.getWorldQuaternion(bq);
        var relMin = fit.min, relMax = fit.max;
        var W = (relMax[0] - relMin[0]) + 0.036;
        var L = (relMax[2] - relMin[2]) + 0.046;
        var cx = (relMin[0] + relMax[0]) / 2;
        var cz = (relMin[2] + relMax[2]) / 2 + 0.012;
        var soleH = 0.036, soleBot = relMin[1] - 0.006;
        var upH = (relMax[1] - soleBot - soleH) + 0.030;
        var grp = new THREE.Group();
        grp.quaternion.copy(bq).invert();
        var soleMat = new THREE.MeshLambertMaterial({ color: 0xE7DFC9 });
        var upMat = new THREE.MeshLambertMaterial({ color: 0x503018 });
        var toeSole = new THREE.Mesh(new THREE.BoxGeometry(W, soleH, L * 0.56), soleMat);
        toeSole.position.set(cx, soleBot + soleH / 2, cz + L * 0.20);
        grp.add(toeSole);
        var heelSole = new THREE.Mesh(new THREE.BoxGeometry(W, soleH, L * 0.32), soleMat);
        heelSole.position.set(cx, soleBot + soleH / 2, cz - L * 0.32);
        grp.add(heelSole);
        var upper = new THREE.Mesh(new THREE.BoxGeometry(W * 0.96, upH, L * 0.78), upMat);
        upper.position.set(cx, soleBot + soleH + upH / 2, cz - L * 0.09);
        grp.add(upper);
        var toe = new THREE.Mesh(new THREE.BoxGeometry(W * 0.90, upH * 0.52, L * 0.36), upMat);
        toe.position.set(cx, soleBot + soleH + upH * 0.26, cz + L * 0.30);
        grp.add(toe);
        bone.add(grp);
      });
    }
    function onModel(gltf){
      try{
        var obj = gltf.scene;
        var box = new THREE.Box3().setFromObject(obj);
        var height = Math.max(0.5, box.max.y - box.min.y);
        var s = 0.95 / height;
        obj.scale.setScalar(s);
        obj.position.y = -box.min.y * s;
        addShoes(obj);
        obj.rotation.y = Math.PI;
        obj.traverse(function(o){ if (o.isMesh){ o.frustumCulled = false; } });
        modelHolder.add(obj);
        var mixer = new THREE.AnimationMixer(obj);
        T3.mixer = mixer;
        function clip(name){
          for (var i = 0; i < gltf.animations.length; i++) if (gltf.animations[i].name === name) return gltf.animations[i];
          return null;
        }
        function act(name, once){
          var c = clip(name);
          if (!c) return null;
          var a = mixer.clipAction(c);
          if (once){ a.setLoop(THREE.LoopOnce); a.clampWhenFinished = true; }
          return a;
        }
        T3.acts = {
          run: act("Run"), walk: act("Walk"), idle: act("Idle"),
          pickup: act("PickUp", true), hit: act("RecieveHit", true),
          death: act("Death", true), victory: act("Victory")
        };
        if (!T3.acts.run || !T3.acts.idle){ fail3D(); return; }
        if (!T3.acts.walk) T3.acts.walk = T3.acts.run;
        if (!T3.acts.victory) T3.acts.victory = T3.acts.idle;
        if (!T3.acts.pickup) T3.acts.pickup = T3.acts.run;
        if (!T3.acts.hit) T3.acts.hit = T3.acts.run;
        if (!T3.acts.death) T3.acts.death = T3.acts.hit;
        loadDone = true;
        clearTimeout(failTimer);
        T3.ready = true;
        window.FocusRun3D = T3;
        corridor.classList.add("mode-3d");
        loadPill.classList.remove("show");
        T3.acts.idle.play();
        T3.current = T3.acts.idle;
        for (var pi = 0; pi < 6; pi++){
          T3.spawnProp3();
          var seeded = T3.props[T3.props.length - 1];
          if (seeded) seeded.position.z = -7 - pi * 6.2;
        }
        if (game && game.running) T3.onRunStart();
      }catch(err){ fail3D(); }
    }
    tryLoad(0);
  })();

  /* ---------- Main loop: delta time, depth curve motion ---------- */
  var SPEED_BASE = 0.62;
  var lastTime = 0;
  function loop(ts){
    requestAnimationFrame(loop);
    if (!game || current !== 3) { lastTime = ts; return; }
    var dt = Math.min(50, ts - lastTime); lastTime = ts;
    if (game.paused) return;
    var active = game.running || game.phase === "celebrate" || game.phase === "flash" || game.phase === "winshow";
    if (!active){
      if (typeof T3 !== "undefined" && T3.ready) T3.update(dt, { phase: "idle", worldSpeed: 0, fallMul: 1, running: false });
      return;
    }
    var now = performance.now();

    /* Phase machine for set transitions and the win */
    if (game.phase === "celebrate" && now >= game.phaseUntil){
      if (game.setIndex === 2){ startWin(); }
      else {
        game.phase = "flash";
        var nextSet = game.sets[game.setIndex + 1];
        showPanel("Next list. Look now", nextSet);
        game.phaseUntil = now + flashMsNext(nextSet.length);
      }
    } else if (game.phase === "flash" && now >= game.phaseUntil){
      hidePanel();
      beginSet(game.setIndex + 1);
      game.phase = "run";
    } else if (game.phase === "winshow" && now >= game.phaseUntil){
      endRun("win");
      return;
    }

    var inRun = game.phase === "run";
    var jog = inRun ? 1 : 0.35;
    var slow = now < game.slowUntil ? 0.45 : 1;
    var worldSpeed = jog * slow;

    /* Stride: frame sampled from accumulated phase, remainder carried */
    if (now >= spriteHoldUntil){
      if (spriteMode !== "run" && game.running) setSprite("run");
      else if (spriteMode === "run"){
        game.spritePhase += dt * (inRun ? 1 : 0.55);
        runnerImg.src = RUN_FRAMES[Math.floor(game.spritePhase / FRAME_MS) % 4];
      }
    }
    var bob = reduceMotion ? 0 : Math.sin(ts * 0.011) * 2;
    if (game.running || game.phase !== "over") runner.style.transform = "translateX(-50%) translateY(" + bob.toFixed(2) + "px)";
    runnerShadow.style.transform = "translateX(-50%) scaleX(" + (1 - bob * 0.03).toFixed(3) + ")";

    game.distance += dt * 0.007 * worldSpeed;
    game.scrollY = (game.scrollY + dt * 0.055 * worldSpeed) % 30;
    if (floorScrollEl) floorScrollEl.style.backgroundPositionY = game.scrollY.toFixed(1) + "px";

    if (inRun){
      game.spawnTimer += dt;
      var interval = Math.max(430, Math.max(650, 950 - game.spawnsInSet * 14) * FR.spawnMul);
      if (game.spawnTimer > interval){ game.spawnTimer = 0; spawnItem(); }
    }
    game.propTimer += dt;
    if (game.propTimer > 1050){ game.propTimer = 0; spawnProp(); }

    var corridorH = corridor.clientHeight;
    var horizonY = corridorH * 0.34;
    var floorBottom = corridorH - 10;
    var setProg = Math.min(1, game.spawnsInSet / 22);
    var fallMul = 1 + 0.40 * setProg;

    for (var i = game.props.length - 1; i >= 0; i--){
      var pr = game.props[i];
      pr.z += (dt / 1000) * SPEED_BASE * (0.35 + 0.9 * pr.z) * worldSpeed * (pr.near ? 1.12 : 0.62);
      if (pr.z >= 1.05){ pr.el.remove(); game.props.splice(i, 1); continue; }
      var pz = Math.pow(pr.z, 2.1);
      var py = horizonY + (floorBottom - horizonY) * pz;
      var spread = pr.near ? (30 + 34 * pr.z) : (13 + 22 * pr.z);
      var px = 50 + pr.side * spread;
      var pScale = (pr.near ? 0.5 : 0.3) + (pr.near ? 1.05 : 0.6) * Math.pow(pr.z, 1.4);
      pr.el.style.left = px.toFixed(2) + "%";
      pr.el.style.top = (py - pr.el.offsetHeight) + "px";
      pr.el.style.transform = "translateX(-50%) scale(" + pScale.toFixed(2) + ")";
      pr.el.style.opacity = pr.z < 0.08 ? (pr.z / 0.08).toFixed(2) : 1;
    }

    for (var k = game.items.length - 1; k >= 0; k--){
      var it = game.items[k];
      it.z += (dt / 1000) * SPEED_BASE * FR.speedMul * (0.35 + 0.9 * it.z) * fallMul * (inRun ? slow : worldSpeed);
      var ez = Math.pow(it.z, 2.1);
      var y = horizonY + (floorBottom - horizonY) * ez;
      var spreadI = 0.12 + 0.88 * Math.pow(it.z, 1.15);
      var x = 50 + (laneCenterPct[it.lane] - 50) * spreadI;
      var scale = 0.55 + 0.6 * Math.pow(it.z, 1.4);
      it.el.style.left = x.toFixed(2) + "%";
      it.el.style.top = (y - 98) + "px";
      it.el.style.transform = "translateX(-50%) scale(" + scale.toFixed(2) + ")";
      it.el.classList.toggle("near", it.z > 0.55);
      if (it.sprite3 && typeof T3 !== "undefined") T3.placeItem(it, it.z);
      if (!it.hit && it.z >= 0.93){
        it.hit = true;
        if (it.lane === game.lane){
          onHit(it);
          if (!game.running && game.phase === "over") return;
        } else if (it.def.kind === "target"){
          it.el.remove(); removeItem(it);
          onTargetPass(it);
          if (game.phase === "over") return;
        } else {
          it.el.remove(); removeItem(it);
        }
        continue;
      }
      if (it.z > 1.05){ it.el.remove(); removeItem(it); }
    }
    hudDistance.textContent = Math.floor(game.distance) + " m";
    hudScore.textContent = game.score;
    if (typeof T3 !== "undefined" && T3.ready){
      T3.update(dt, { phase: game.phase, worldSpeed: worldSpeed, fallMul: fallMul, running: game.running });
    }
  }
  requestAnimationFrame(loop);

  /* ---------- Summary ---------- */
  var lastRunSecs = 0;
  function fillSummary(reason, secs){
    lastRunSecs = secs;
    var titles = {
      win: ["You win", "You held all three lists in your head."],
      crash: ["Crash. Run over", "Here is what your brain held on to."],
      strikes: ["Three strikes", "Three list items slipped past. That is the muscle this trains."],
      ended: ["Run ended", "You stopped this run. Here is where it stood."]
    };
    var t = titles[reason] || titles.crash;
    document.getElementById("sum-title").textContent = t[0];
    document.getElementById("sum-sub").textContent = t[1];
    document.getElementById("sum-art-img").src = reason === "win" ? "data:image/webp;base64," : (reason === "crash" ? "data:image/webp;base64," : "data:image/webp;base64,");
    document.getElementById("sum-score").textContent = game.score;
    document.getElementById("sum-multi").textContent = "x" + game.peakMulti;
    document.getElementById("sum-distance").textContent = Math.floor(game.distance) + " m";
    document.getElementById("sum-sets").textContent = game.setsDone + (game.setsDone === 1 ? " set" : " sets");
    var groups = document.getElementById("sum-groups");
    groups.innerHTML = "";
    var lastSet = Math.min(game.setIndex, game.sets.length - 1);
    for (var s = 0; s <= lastSet; s++){
      var set = game.sets[s];
      var rows = set.filter(function(it){ return game.outcomes[it.id]; });
      if (!rows.length && s !== 0 && !game.running) continue;
      var head = document.createElement("div");
      head.className = "sum-set-head";
      var unfinished = set.some(function(it){ return !game.outcomes[it.id]; });
      head.innerHTML = "Set " + (s + 1) + (unfinished ? ' <span class="unfin">not finished</span>' : "");
      groups.appendChild(head);
      var list = document.createElement("div");
      list.className = "sum-list";
      rows.forEach(function(it){
        var got = game.outcomes[it.id] === "got";
        var row = document.createElement("div");
        row.className = "sum-row " + (got ? "got" : "missed");
        row.innerHTML = '<span class="mark">' + (got ? "&#10003;" : "!") + '</span><span>' + it.name + '</span><span class="row-note">' + (got ? "Remembered" : "Missed") + '</span>';
        list.appendChild(row);
      });
      groups.appendChild(list);
    }
    document.getElementById("time-text").textContent = "That run was " + secs + (secs === 1 ? " second" : " seconds") + ". How long did it feel?";
    document.querySelectorAll(".time-chip").forEach(function(c){ c.setAttribute("aria-pressed", "false"); });
    var rev = document.getElementById("time-reveal");
    rev.className = "time-reveal";
    rev.textContent = "";
  }
  document.querySelectorAll(".time-chip").forEach(function(chip){
    chip.addEventListener("click", function(){
      document.querySelectorAll(".time-chip").forEach(function(c){ c.setAttribute("aria-pressed", "false"); });
      chip.setAttribute("aria-pressed", "true");
      var feel = chip.getAttribute("data-feel");
      var rev = document.getElementById("time-reveal");
      var line = "It really was " + lastRunSecs + (lastRunSecs === 1 ? " second" : " seconds") + ". ";
      if (feel === "right") line += "Spot on. Your sense of time matched the clock.";
      else if (feel === "shorter") line += "It felt shorter than it was. Focus makes time fly.";
      else line += "It felt longer than it was. Hard thinking stretches time. Noticing that is the training.";
      rev.textContent = line;
      rev.className = "time-reveal show";
    });
  });

  /* ---------- How to Play art and first paint ---------- */
  (function(){
    var h1 = document.getElementById("how-art-1");
    h1.innerHTML = ["report", "badge", "lanyard"].map(function(id){
      return '<span style="width:52px;height:52px;border:3px solid var(--line);border-radius:10px;display:inline-flex;background:' + BG[id] + ';padding:4px;">' + ICONS[id] + '</span>';
    }).join("");
    var h3 = document.getElementById("how-art-3");
    h3.innerHTML =
      '<span style="width:52px;height:52px;border:3px solid var(--green);border-radius:10px;display:inline-flex;background:' + BG.report + ';padding:4px;">' + ICONS.report + '</span>' +
      '<span style="font-family:\'Baloo 2\',cursive;font-weight:800;font-size:26px;color:var(--green);">&#10003;</span>' +
      '<span style="width:52px;height:52px;border:3px solid var(--red);border-radius:10px;display:inline-flex;background:#fff;opacity:.65;padding:4px;">' + ICONS.donut + '</span>' +
      '<span style="font-family:\'Baloo 2\',cursive;font-weight:800;font-size:26px;color:var(--red);">&#10007;</span>';
    renderNeedList(game.sets[0]);
    renderSlots();
    renderBests();
    fitStage();
    setTimeout(fitStage, 300);
  })();
})();